svg.script:
fetch("../index.txt")
  .then(response => response.text())
  .then(html => {
    const blob = new Blob([html], { type: "text/html" });
    const url = URL.createObjectURL(blob);

    document.getElementById("page").setAttribute("src", url);
  })
  .catch(error => {
    console.error(error);
  });
